import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_request_signature(f):
    """Verify HMAC signature of request body for webhook endpoints."""
    @wraps(f)
    def decorated(*args, **kwargs):
        sig = request.headers.get('X-Signature-256', '')
        if not sig:
            return jsonify({'error': 'missing signature'}), 401
        body = request.get_data()
        expected = 'sha256=' + hmac.new(
            SECRET_KEY.encode(), body, hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 403
        return f(*args, **kwargs)
    return decorated

def sanitize_display_name(name):
    """Basic XSS prevention for display names."""
    return name.replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role.
    Supports flexible filtering for the internal admin dashboard.
    """
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    status = request.args.get('status', 'active')

    # Build query with filters
    base_query = "SELECT id, username, display_name, email, department, role FROM users WHERE status = '{}'".format(status)

    if department:
        base_query += " AND department = '{}'".format(department)
    if role:
        base_query += " AND role = '{}'".format(role)

    base_query += " ORDER BY username ASC LIMIT 50"

    db = get_db()
    try:
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        # Sanitize display names before returning
        for r in results:
            r['display_name'] = sanitize_display_name(r['display_name'])
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - uses parameterized query."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, display_name, email, department, role FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        result = dict(user)
        result['display_name'] = sanitize_display_name(result['display_name'])
        return jsonify(result)
    return jsonify({'error': 'not found'}), 404

@app.route('/api/webhook/user-sync', methods=['POST'])
@verify_request_signature
def sync_user():
    """Webhook endpoint for HR system user sync."""
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'invalid payload'}), 400
    db = get_db()
    db.execute(
        "INSERT OR REPLACE INTO users (username, display_name, email, department, role, status) VALUES (?, ?, ?, ?, ?, ?)",
        (data['username'], data.get('display_name', ''), data.get('email', ''),
         data.get('department', ''), data.get('role', ''), data.get('status', 'active'))
    )
    db.commit()
    return jsonify({'status': 'synced'}), 200

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
